// Config plugin: configurable release signing for the generated Android project.
//
// `android/` is regenerated by `expo prebuild`, so signing can't be hand-edited
// into build.gradle. This plugin patches it on every prebuild:
//
// - Gradle property `anvilReleaseStoreFile` set (plus `anvilReleaseStorePassword`,
//   `anvilReleaseKeyAlias`, `anvilReleaseKeyPassword`) → release APKs are signed
//   with that keystore. Keep these in ~/.gradle/gradle.properties or pass them
//   as -P flags — never commit them.
// - `-PanvilUnsigned=true` → release APK is left unsigned (what F-Droid's build
//   server expects; it signs with its own key).
// - Neither → unchanged Expo default (debug keystore), so local
//   `expo run:android --variant release` keeps working.
//
// EAS Build injects its own signing config and is unaffected.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// anvil:release-signing';

const SIGNING_CONFIG = `
        ${MARKER}
        release {
            if (project.hasProperty('anvilReleaseStoreFile')) {
                storeFile file(project.property('anvilReleaseStoreFile'))
                storePassword project.property('anvilReleaseStorePassword')
                keyAlias project.property('anvilReleaseKeyAlias')
                keyPassword project.property('anvilReleaseKeyPassword')
            }
        }`;

const RELEASE_SIGNING = `${MARKER}
            if (project.hasProperty('anvilReleaseStoreFile')) {
                signingConfig signingConfigs.release
            } else if ((findProperty('anvilUnsigned') ?: 'false').toBoolean()) {
                signingConfig null
            } else {
                signingConfig signingConfigs.debug
            }`;

function patchBuildGradle(contents) {
  if (contents.includes(MARKER)) {
    return contents;
  }

  // 1. Add a `release` signing config next to the template's `debug` one.
  const signingConfigs = /signingConfigs\s*\{\s*\n(\s*debug\s*\{[^}]*\})/;
  if (!signingConfigs.test(contents)) {
    throw new Error('[with-release-signing] signingConfigs.debug block not found in app/build.gradle');
  }
  contents = contents.replace(signingConfigs, (match) => `${match}${SIGNING_CONFIG}`);

  // 2. Point the release build type at it (the template uses the debug key).
  const releaseBuildType = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;
  if (!releaseBuildType.test(contents)) {
    throw new Error('[with-release-signing] release buildType signingConfig not found in app/build.gradle');
  }
  return contents.replace(releaseBuildType, (_match, before) => `${before}${RELEASE_SIGNING}`);
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error('[with-release-signing] expected a Groovy app/build.gradle');
    }
    cfg.modResults.contents = patchBuildGradle(cfg.modResults.contents);
    return cfg;
  });
};

module.exports.patchBuildGradle = patchBuildGradle;
